<?php
require_once "inc/config.php"; require_once "inc/admin_auth.php"; require_admin_permission($pdo,'moderation');
$status=(string)($_GET['status']??'');$q=trim((string)($_GET['q']??''));$where=[];$p=[];
if(in_array($status,['pending','active','expired','cancelled','draft'],true)){$where[]='t.status=?';$p[]=$status;}
if($q!==''){$where[]='(t.title LIKE ? OR CAST(t.id AS CHAR)=? OR c.full_name LIKE ?)';$like="%$q%";array_push($p,$like,$q,$like);}
$sql="SELECT t.id,t.title,t.status,t.start_date,t.end_date,t.budget_min,t.budget_max,t.currency,c.full_name vendor_name FROM tenders t JOIN customers c ON c.id=t.customer_id";if($where)$sql.=" WHERE ".implode(' AND ',$where);$sql.=" ORDER BY t.id DESC LIMIT 100";$stmt=$pdo->prepare($sql);$stmt->execute($p);$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);$csrf=admin_csrf_token();
?>
<!doctype html><html lang="az"><head><?php include "inc/head.php"; ?></head><body><div class="app-main"><div id="app-wrapper" class="app-wrapper d-flex flex-column align-items-stretch min-vh-100"><?php include "inc/sidebar.php"; ?><?php include "inc/navbar.php"; ?><div class="app-content-wrapper py-13"><div class="container-fluid"><div class="page-header pb-7"><h2 class="fw-semibold fs-7">Tender moderasiyası</h2></div><form class="row g-3 mb-5"><div class="col-md-6"><input class="form-control" name="q" value="<?=admin_h($q)?>" placeholder="Başlıq, vendor və ya ID"></div><div class="col-md-4"><select class="form-control" name="status"><option value="">Bütün statuslar</option><?php foreach(['pending','active','expired','cancelled','draft'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Filtr</button></div></form><div class="pure-card card-bg shadow-custom rounded-custom"><div class="pure-card-body table-responsive"><table class="table"><tr><th>ID</th><th>Tender</th><th>Vendor</th><th>Status</th><th>Tarix</th><th>Əməliyyat</th></tr><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=admin_h($r['title'])?><br><?=admin_h($r['budget_min'].'-'.$r['budget_max'].' '.$r['currency'])?></td><td><?=admin_h($r['vendor_name'])?></td><td><?=admin_h($r['status'])?></td><td><?=admin_h($r['start_date'])?> → <?=admin_h($r['end_date'])?></td><td><form method="post" action="api/management/tender_moderation.php" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" class="form-control form-control-sm"><option value="active">Aktiv et</option><option value="pending">Gözləməyə al</option><option value="cancelled">Ləğv et</option></select><input name="reason" class="form-control form-control-sm" placeholder="Səbəb"><button class="btn btn-sm btn-primary">Tətbiq</button></form></td></tr><?php endforeach;?></table></div></div></div></div><?php include "inc/footer.php"; ?></div></div><?php include "inc/scripts_url.php"; ?></body></html>
